<?php
require __DIR__.'/app/bootstrap.php';

$userId=require_auth();$tripId=(int)($_GET['id']??$_POST['trip_id']??0);if($tripId<1){http_response_code(400);exit('Trip is required.');}
$service=new TripCostIntelligenceService(db());$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();
    try{
        if(!$service->ready())throw new RuntimeException('Run System Upgrade for Trip Cost Intelligence + True Trip Economics.');
        $action=(string)($_POST['action']??'');
        if($action==='save_plan'){$service->saveCategoryPlan($userId,$tripId,$_POST);flash('success','Category budget updated.');}
        elseif($action==='add_expense'){$service->addExpense($userId,$tripId,$_POST);flash('success','Actual expense added to the owner ledger.');}
        elseif($action==='void_expense'){$service->voidExpense($userId,$tripId,(int)($_POST['entry_id']??0),(string)($_POST['void_reason']??''));flash('success','Expense correction recorded. The original ledger row remains auditable.');}
        else throw new InvalidArgumentException('Unknown cost action.');
        redirect('trip-cost.php?id='.$tripId);
    }catch(InvalidArgumentException|DomainException|OutOfBoundsException $e){$error=$e->getMessage();}
    catch(Throwable $e){error_log('Trip Cost Intelligence update failed: '.$e->getMessage());$error='Vacation Brain could not update trip costs safely. '.$e->getMessage();}
}
try{$snapshot=$service->snapshot($userId,$tripId);}catch(OutOfBoundsException $e){http_response_code(404);exit('Trip not found.');}
$trip=$snapshot['trip'];$success=flash('success');$title='True Trip Economics — '.$trip['name'];$pageStyles=['assets/trip-cost-intelligence.css'];
function vb_cost_label(string $v):string{return ucwords(str_replace('_',' ',$v));}
function vb_cost_money(mixed $v,string $c):string{return $v===null||$v===''?'—':($c==='USD'?'$':$c.' ').number_format((float)$v,2);}
function vb_cost_dt(mixed $v):string{$s=trim((string)$v);if($s==='')return ''; $t=strtotime($s);return $t?date('M j, Y g:i A',$t):$s;}
$tripCurrency=(string)($trip['currency']??'USD');$owner=!empty($snapshot['can_manage']);$econ=$snapshot['economics']['by_currency'][$tripCurrency]??null;$bookingTrip=(float)($snapshot['shared']['bookings']['by_currency'][$tripCurrency]??0);$model=$snapshot['history_model']['currencies'][$tripCurrency]??null;
require __DIR__.'/partials/header.php';
?>
