<article><span>Reported actual</span><strong><?=$owner&&$econ&&$econ['reported_actual']!==null?e(vb_cost_money($econ['reported_actual'],$tripCurrency)):'—'?></strong><small><?=$owner?'Trip Memory traveler-reported total':'Owner only'?></small></article>
</section>
<?php if(!$owner):?>
