<div><span>Structured gross</span><b><?=e(vb_cost_money($row['structured_gross_cash_outflow'],$currency))?></b></div><div><span>Cash recovered</span><b><?=e(vb_cost_money($row['cash_recovered'],$currency))?></b></div><div><span>Provider credits</span><b><?=e(vb_cost_money($row['credits_received'],$currency))?></b></div><div><span>Cash still expected</span><b><?=e(vb_cost_money($row['cash_outstanding'],$currency))?></b></div><div><span>Per traveler / day</span><b><?=e(vb_cost_money($row['per_traveler_day'],$currency))?></b></div><div><span>Budget variance</span><b class="<?=($variance??0)>0?'vb-cost-danger':'vb-cost-good'?>"><?=e($variance===null?'—':vb_cost_money($variance,$currency))?></b></div>
</div></article><?php endforeach;?>
</div></section>
