<?php foreach((array)($snapshot['economics']['categories']??[]) as $currency=>$categories):?><div class="vb-cost-table-wrap"><table class="vb-cost-table"><thead><tr><th><?=e($currency)?> category</th><th>Plan</th><th>Bookings</th><th>Actual extras</th><th>Disruption</th><th>Cash recovered</th><th>Net cash</th><th>Credits</th></tr></thead><tbody><?php foreach($categories as $cat=>$r):?><tr><td><?=e($snapshot['categories'][$cat]??vb_cost_label($cat))?></td><td><?=e(vb_cost_money($r['planned'],$currency))?></td><td><?=e(vb_cost_money($r['booking_cost'],$currency))?></td><td><?=e(vb_cost_money($r['manual_cost'],$currency))?></td><td><?=e(vb_cost_money($r['disruption_cost'],$currency))?></td><td><?=e(vb_cost_money($r['cash_recovered'],$currency))?></td><td><?=e(vb_cost_money($r['net_cash_cost'],$currency))?></td><td><?=e(vb_cost_money($r['credits_received'],$currency))?></td></tr><?php endforeach;?></tbody></table></div><?php endforeach;?>
